var i=`0330-crepes-suzette`;var a=`world-0330`;var n=`FR`;var r=`western-europe`;var s=8;var u=35;var g={en:`Crêpes Suzette`,ua:`Креп-сюзетт`};var l={en:`Classic crêpes in orange-butter sauce with brandy as a substitute for orange liqueur, which is not cataloged.`,ua:`Класичні млинці в апельсиново-масляному соусі; замість відсутнього в каталозі апельсинового лікеру використано бренді.`};var o=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:7,i:[[`all-purpose-flour`,200,`g`],[`chicken-egg`,3,`pcs`],[`whole-cow-milk`,440,`ml`],[`unsalted-butter`,40,`g`],[`white-granulated-sugar`,30,`g`]]},{en:`Swirl thin layers of batter in a lightly greased hot pan. Cook both sides, about 18 minutes per batch, to make flexible crepes.`,ua:`Наливайте тонкий шар тіста на злегка змащену розігріту сковороду. Обсмажуйте з обох боків, приблизно 18 хвилин на партію, щоб отримати еластичні млинці.`,t:[`pan-frying`],m:18,i:[[`unsalted-butter`,35,`g`]]},{en:`Heat the listed ingredients over moderate heat, stirring only as needed, for about 8 minutes until amber and fragrant.`,ua:`Нагрівайте зазначені складники на помірному вогні приблизно 8 хвилин до бурштинового кольору й аромату, помішуючи за потреби.`,t:[`caramelizing-sugar`],m:8,i:[[`orange-juice`,220,`ml`],[`orange-zest`,9,`g`],[`white-granulated-sugar`,110,`g`],[`unsalted-butter`,65,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`brandy`,45,`ml`]]}];var h={slug:i,id:a,country:`FR`,region:r,servings:8,minutes:35,title:g,text:l,steps:o};export{n as country,h as default,a as id,u as minutes,r as region,s as servings,i as slug,o as steps,l as text,g as title};